#nullable enable // autogenerated

using MVZ2.GameContent.Detections;
using MVZ2.Vanilla.Audios;
using MVZ2.Vanilla.Detections;
using MVZ2.Vanilla.Effects;
using MVZ2.Vanilla.Entities;
using MVZ2.Vanilla.Properties;
using MVZ2Logic.Entities;
using PVZEngine;
using PVZEngine.Collisions;
using PVZEngine.Definitions;
using PVZEngine.Entities;
using PVZEngine.Models;
using PVZEngine.Modifiers;
using PVZEngine.Tools.Timing;
using PVZEngine.Tools.Unity;
using UnityEngine;

namespace MVZ2.GameContent.Effects
{
    [AutoEntityBehaviourDefinition(VanillaEffectNames.miracleMalletMinion)]
    public class MiracleMalletMinion : EntityBehaviourDefinition
    {
        public MiracleMalletMinion(string nsp, string name) : base(nsp, name)
        {
            AddModifier(new BooleanModifier(EngineEntityProps.FLIP_X, PROP_FLIP));
        }
        public override void Init(Entity entity)
        {
            base.Init(entity);
            var pos = entity.Position;
            pos.y = entity.GetGroundY() + IDLE_SUSPENSION_HEIGHT;
            SetTargetPosition(entity, pos);
        }
        public override void Update(Entity entity)
        {
            base.Update(entity);
            int targetState = STATE_IDLE;
            if (entity.Target.ExistsAndAlive())
            {
                targetState = STATE_ATTACK;
            }
            if (entity.State != targetState)
            {
                switch (targetState)
                {
                    case STATE_IDLE:
                        StartIdleState(entity);
                        break;
                    case STATE_ATTACK:
                        StartAttackState(entity);
                        break;
                }
                entity.State = targetState;
            }

            switch (entity.State)
            {
                case STATE_IDLE:
                    IdleUpdate(entity);
                    break;
                case STATE_ATTACK:
                    AttackUpdate(entity);
                    break;
            }

            var attackTimer = GetOrCreateAttackTimerSeconds(entity, ATTACK_INTERVAL_SECONDS);
            attackTimer.Run(entity.GetAttackSpeed());

            var sign = Mathf.Sign(entity.Velocity.x);
            if (Mathf.Abs(entity.Velocity.x) > 0.2f)
            {
                SetFlip(entity, sign < 0);
            }
        }
        private void IdleUpdate(Entity entity)
        {
            var targetPosition = GetTargetPosition(entity);
            var timer = GetOrCreateStateTimerSeconds(entity, WANDER_SECONDS);
            if (timer.RunToExpired())
            {
                timer.Reset();
                targetPosition = FindWanderPosition(entity);
                SetTargetPosition(entity, targetPosition);
            }
            ChaseTarget(entity, targetPosition, 0.5f);

            if (entity.IsTimeInterval(FIND_TARGET_INTERVAL))
            {
                var newTarget = FindTarget(entity);
                entity.Target = newTarget;
            }
        }
        private void AttackUpdate(Entity entity)
        {
            var target = entity.Target;
            if (!target.ExistsAndAlive())
                return;
            ChaseTarget(entity, target.GetCenter(), 0.1f);
            var mainCollider = target.GetMainCollider();
            var range = entity.GetRange();
            if (mainCollider != null && mainCollider.CheckSphere(entity.GetCenter(), range))
            {
                var attackTimer = GetOrCreateAttackTimerSeconds(entity, ATTACK_INTERVAL_SECONDS);
                if (attackTimer.Expired)
                {
                    attackTimer.Reset();
                    Whack(entity, target);

                    var newTarget = FindTarget(entity);
                    entity.Target = newTarget;
                }
            }
        }
        private void StartIdleState(Entity entity)
        {
            var pos = entity.Position;
            SetTargetPosition(entity, pos);
        }
        private void StartAttackState(Entity entity)
        {
        }
        public static void Whack(Entity entity, Entity target)
        {
            entity.Spawn(VanillaEffectID.pow, entity.GetCenter());
            entity.TriggerAnimation("Whack");
            entity.PlaySound(VanillaSoundID.bonk);
            if (target.CanDeactive())
            {
                target.Stun(STUN_DURATION);
            }
        }
        private static Entity? FindTarget(Entity entity)
        {
            return targetDetector.DetectEntityWithTheLeast(entity, t => t.Position.x);
        }
        private static Vector3 FindWanderPosition(Entity entity)
        {
            var column = entity.GetColumn();
            var lane = entity.GetLane();
            var minColumn = Mathf.Max(0, column - WANDER_TILE_EXTENT);
            var maxColumn = Mathf.Min(entity.Level.GetMaxColumnCount() - 1, column + WANDER_TILE_EXTENT);
            var minLane = Mathf.Max(0, lane - WANDER_TILE_EXTENT);
            var maxLane = Mathf.Min(entity.Level.GetMaxLaneCount() - 1, lane + WANDER_TILE_EXTENT);

            var rng = entity.RNG;
            var angle = rng.Next(0, 360f);
            var distance = rng.Next(0, WANDER_MAX_OFFSET);
            var finalColumn = rng.Next(minColumn, maxColumn + 1);
            var finalLane = rng.Next(minLane, maxLane + 1);
            var tilePosition = entity.Level.GetEntityGridPosition(finalColumn, finalLane);
            var tileOffset = Vector2.right.RotateClockwise(angle) * distance;
            var finalPosition = tilePosition;
            tilePosition.x += tileOffset.x;
            tilePosition.z += tileOffset.y;
            tilePosition.y = entity.Level.GetGroundY(tilePosition.x, tilePosition.z) + IDLE_SUSPENSION_HEIGHT;
            return tilePosition;
        }
        private static void ChaseTarget(Entity entity, Vector3 targetPosition, float factor)
        {
            var velocity = entity.Velocity;
            var distance = (targetPosition - entity.Position);
            var speed = Mathf.Clamp(distance.magnitude * SPEED_MULTIPLIER_BY_DISTANCE + CHASE_SPEED_OFFSET, 0, MAX_SPEED);
            var direction = distance.normalized;

            var targetVelocity = direction * speed;
            velocity = velocity * (1 - factor) + targetVelocity * factor;
            entity.Velocity = velocity;
        }
        private static bool ColliderFilter(DetectionParams args, IEntityCollider collider)
        {
            var entity = collider.Entity;
            if (!entity.CanDeactive())
            {
                return false;
            }
            return true;
        }
        public static Vector3 GetTargetPosition(Entity entity) => entity.GetProperty<Vector3>(PROP_TARGET_POSITION);
        public static void SetTargetPosition(Entity entity, Vector3 value) => entity.SetProperty(PROP_TARGET_POSITION, value);
        public static bool IsFlip(Entity entity) => entity.GetProperty<bool>(PROP_FLIP);
        public static void SetFlip(Entity entity, bool value) => entity.SetProperty(PROP_FLIP, value);
        public static FrameTimer GetOrCreateStateTimerSeconds(Entity entity, float seconds) => entity.GetOrCreateTimerSeconds(PROP_STATE_TIMER, seconds);
        public static FrameTimer GetOrCreateAttackTimerSeconds(Entity entity, float seconds) => entity.GetOrCreateTimerSeconds(PROP_ATTACK_TIMER, seconds);
        public const int STATE_IDLE = VanillaEffectStates.IDLE;
        public const int STATE_ATTACK = VanillaEffectStates.MIRACLE_MALLET_MINION_ATTACK;
        public const int WANDER_TILE_EXTENT = 1;
        public const int WANDER_MAX_OFFSET = 40;
        public const float SPEED_MULTIPLIER_BY_DISTANCE = 0.2f;
        public const float CHASE_SPEED_OFFSET = -SPEED_MULTIPLIER_BY_DISTANCE;
        public const float MAX_SPEED = 20f;
        public const float IDLE_SUSPENSION_HEIGHT = 40f;
        public const int FIND_TARGET_INTERVAL = 7;
        public const int WANDER_SECONDS = 5;
        public const float ATTACK_INTERVAL_SECONDS = 3;
        public const int STUN_DURATION = 60;
        public static readonly Detector targetDetector = new LawnDetector()
        {
            colliderFilter = ColliderFilter,
            mask = EntityCollisionHelper.MASK_ENEMY
        };
        public static readonly PropertyMeta<Vector3> PROP_TARGET_POSITION = new VanillaEntityPropertyMeta<Vector3>("target_position");
        public static readonly PropertyMeta<FrameTimer> PROP_STATE_TIMER = new VanillaEntityPropertyMeta<FrameTimer>("state_timer");
        public static readonly PropertyMeta<FrameTimer> PROP_ATTACK_TIMER = new VanillaEntityPropertyMeta<FrameTimer>("attack_timer");
        public static readonly PropertyMeta<bool> PROP_FLIP = new VanillaEntityPropertyMeta<bool>("flip");
    }
}